def _addr(v):
    return currentProgram.getAddressFactory().getDefaultAddressSpace().getAddress(v)


def main():
    print("=== FixF01Seg7LiteralPools2 (DRY=%s) ===" % DRY)
    listing = currentProgram.getListing()
    dt = DWordDataType()
    nok = nfail = 0

    for addr_int, expected_val in LITERAL_POOL_TARGETS:
        if DRY:
            print("[dry] createDWord @ 0x%08x (0x%08x)" % (addr_int, expected_val))
            nok += 1
            continue

        addr = _addr(addr_int)
        try:
            clearListing(addr, _addr(addr_int + 3))
            du = listing.createData(addr, dt)
            if du is not None:
                nok += 1
            else:
                print("[warn] createData returned None @ 0x%08x" % addr_int)
                nfail += 1
        except Exception as e:
            print("[warn] createDWord @ 0x%08x: %s" % (addr_int, e))
            nfail += 1

    print("=== DONE: ok=%d fail=%d ===" % (nok, nfail))


main()
